// ==========================
// Gmail Sanitizer with Label Filter
// ==========================

const email = items[0].json;

const fromEmail =
  email.from?.value?.[0]?.address ||
  email.from?.text ||
  "";

const subject = email.subject || "";

let body =
  email.text ||
  email.textAsHtml ||
  email.html ||
  "";

const labelIds = email.labelIds || [];

// --------------------------
// 🚫 فلترة مبكرة لتقليل التوكنز
// --------------------------

// تجاهل الرسائل المرسلة
if (labelIds.includes("SENT")) {
  return [];
}

// تجاهل Promotions
if (labelIds.includes("CATEGORY_PROMOTIONS")) {
  return [];
}

// تجاهل Social
if (labelIds.includes("CATEGORY_SOCIAL")) {
  return [];
}

// تجاهل Spam من Gmail
if (labelIds.includes("SPAM")) {
  return [];
}

// تنظيف بسيط
body = body.replace(/<[^>]+>/g, " ");
body = body.replace(/\s+/g, " ").trim();

// إخراج موحد
return [{
  json: {
    source: "gmail",
    from: fromEmail,
    subject,
    body

  }
}];

