const leadScore = $input.first().json.output.lead_score || 0;
const urgency = $input.first().json.output.urgency || "Low";

let priority = "Low";
let sla_hours = 48;
let routing_group = "General";

if (leadScore >= 85 || urgency === "High") {
  priority = "Critical";
  sla_hours = 2;
  routing_group = "Immediate Action";
}
else if (leadScore >= 65) {
  priority = "High";
  sla_hours = 8;
  routing_group = "Sales Priority";
}
else if (leadScore >= 40) {
  priority = "Medium";
  sla_hours = 24;
  routing_group = "Follow Up";
}
else {
  priority = "Low";
  sla_hours = 72;
  routing_group = "Low Priority";
}

const ai = $json.output;

return [{
  json: {

      ...ai,
      priority,
      sla_hours,
      routing_group

  }
}];

